import React, { useRef } from 'react';
import { I18nProvider, useButton, useCalendar, useCalendarCell, useCalendarGrid, useLocale } from 'react-aria';
import { useCalendarState, CalendarState } from 'react-stately';
import { CalendarDate, DateValue, createCalendar, getLocalTimeZone, isToday, today } from '@internationalized/date';
import type { AriaCalendarProps, AriaButtonProps } from 'react-aria';
import { Spark, SparkHandle } from '../Spark';
import { cx } from '../internal/cx';
import { useDefaults } from '../internal/defaults';
import { CalendarSystem, FirstDayOfWeek, fromDateValue, toDateValue, toFirstDay, withCalendar } from './dateAdapters';

export interface CalendarProps {
  /** The selected day. */
  value?: Date | null;
  /** Initial selected day when uncontrolled. */
  defaultValue?: Date | null;
  /** Called with the picked day. */
  onChange?: (date: Date) => void;
  /** Earliest selectable day. */
  min?: Date;
  /** Latest selectable day. */
  max?: Date;
  /** Return `true` for days that can't be picked (e.g. weekends, holidays). */
  isDateDisabled?: (date: Date) => boolean;
  /** First day of the week. Defaults to the locale's convention. */
  firstDayOfWeek?: FirstDayOfWeek;
  /** @deprecated Use `firstDayOfWeek`. 0 = Sunday, 1 = Monday. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  /** BCP 47 locale for names, digits and direction. Defaults to SparkProvider's or the browser's. */
  locale?: string;
  /** Calendar system to display, e.g. `indian` (Saka), `islamic-umalqura`, `buddhist`. Values stay JS Dates. */
  calendar?: CalendarSystem;
  /** Move keyboard focus into the grid when the calendar mounts. */
  autoFocus?: boolean;
  /** Label for the "Today" shortcut, for other languages. */
  todayLabel?: string;
  /** Called on Escape, so a custom popover can close. */
  onEscape?: () => void;
  /** Accessible name for the calendar. */
  'aria-label'?: string;
  className?: string;
}

/**
 * Calendar: a month grid. The selected day is a lit node, today is a ring,
 * and picking a day throws a spark. Behaviour comes from React Aria: arrows,
 * Page Up/Down (Shift for years), Home/End, right-to-left mirroring,
 * localized names and digits, other calendar systems, and announcements
 * when the month changes.
 *
 * Style hooks: `.sp-calendar`, `__nav`, `__title`, `__grid`, `__weekday`,
 * `__day` with `[data-selected]`, `[data-today]`, `[data-outside]`,
 * `[data-unavailable]`, `[data-disabled]`, `[data-focus-visible]`.
 */
export function Calendar(inProps: CalendarProps) {
  const { value, defaultValue, onChange, min, max, isDateDisabled, firstDayOfWeek, weekStartsOn, locale, calendar, ...rest } = useDefaults(
    'Calendar',
    inProps,
  );
  const { locale: inherited } = useLocale();
  return (
    <I18nProvider locale={withCalendar(locale ?? inherited, calendar)}>
      <CalendarCore
        value={value === undefined ? undefined : toDateValue(value)}
        defaultValue={toDateValue(defaultValue)}
        onChange={(v) => v && onChange?.(fromDateValue(v)!)}
        minValue={toDateValue(min) ?? undefined}
        maxValue={toDateValue(max) ?? undefined}
        isDateUnavailable={isDateDisabled ? (d) => isDateDisabled(fromDateValue(d)!) : undefined}
        firstDayOfWeek={firstDayOfWeek ?? toFirstDay(weekStartsOn)}
        {...rest}
      />
    </I18nProvider>
  );
}

export interface CalendarCoreProps extends AriaCalendarProps<DateValue> {
  firstDayOfWeek?: FirstDayOfWeek;
  todayLabel?: string;
  onEscape?: () => void;
  className?: string;
}

/** React Aria-level calendar, also used inside DatePicker's popover. */
export function CalendarCore({ todayLabel = 'Today', onEscape, className, firstDayOfWeek, ...props }: CalendarCoreProps) {
  const { locale, direction } = useLocale();
  const sparkRef = useRef<SparkHandle>(null);
  const lastPointer = useRef<{ clientX: number; clientY: number } | null>(null);

  const onChange = (v: DateValue) => {
    const p = lastPointer.current;
    sparkRef.current?.burst(p ? (p as unknown as React.MouseEvent<HTMLElement>) : undefined);
    lastPointer.current = null;
    props.onChange?.(v as never);
  };

  const state = useCalendarState({ ...props, onChange, firstDayOfWeek, locale, createCalendar });
  const { calendarProps, prevButtonProps, nextButtonProps, title } = useCalendar({ ...props, onChange }, state);
  const todayDate = today(getLocalTimeZone());
  const todayBlocked = state.isCellUnavailable(todayDate) || state.isInvalid(todayDate);

  return (
    <div
      {...calendarProps}
      dir={direction}
      className={cx('sp-calendar', className)}
      onPointerDown={(e) => (lastPointer.current = { clientX: e.clientX, clientY: e.clientY })}
      onKeyDown={(e) => {
        if (e.key === 'Escape' && onEscape) onEscape();
      }}
    >
      <div className="sp-calendar__header">
        <NavButton {...prevButtonProps} direction={direction} kind="prev" />
        <h2 className="sp-calendar__title">{title}</h2>
        <NavButton {...nextButtonProps} direction={direction} kind="next" />
      </div>
      <CalendarGrid state={state} firstDayOfWeek={firstDayOfWeek} />
      <div className="sp-calendar__footer">
        <button
          type="button"
          className="sp-calendar__today"
          disabled={todayBlocked || state.isDisabled}
          onClick={(e) => {
            lastPointer.current = { clientX: e.clientX, clientY: e.clientY };
            state.setFocusedDate(todayDate);
            state.selectDate(todayDate);
          }}
        >
          {todayLabel}
        </button>
      </div>
      <Spark ref={sparkRef} count={8} spread={40} />
    </div>
  );
}

function NavButton({ kind, direction, ...props }: AriaButtonProps & { kind: 'prev' | 'next'; direction: 'ltr' | 'rtl' }) {
  const ref = useRef<HTMLButtonElement>(null);
  const { buttonProps } = useButton(props, ref);
  // Arrows point the way time moves, so they swap in right-to-left languages.
  const pointsLeft = (kind === 'prev') === (direction === 'ltr');
  return (
    <button {...buttonProps} ref={ref} className="sp-calendar__nav">
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
        <path d={pointsLeft ? 'M10 3L5 8l5 5' : 'M6 3l5 5-5 5'} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </button>
  );
}

function CalendarGrid({ state, firstDayOfWeek }: { state: CalendarState; firstDayOfWeek?: FirstDayOfWeek }) {
  const { gridProps, headerProps, weekDays, weeksInMonth } = useCalendarGrid({ firstDayOfWeek, weekdayStyle: 'short' }, state);
  return (
    <table {...gridProps} className="sp-calendar__grid">
      <thead {...headerProps}>
        <tr>
          {weekDays.map((day, i) => (
            <th key={i} className="sp-calendar__weekday">
              {day}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {Array.from({ length: weeksInMonth }, (_, week) => (
          <tr key={week}>
            {state.getDatesInWeek(week).map((date, i) =>
              date ? <CalendarCell key={i} state={state} date={date} /> : <td key={i} className="sp-calendar__cell" />,
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function CalendarCell({ state, date }: { state: CalendarState; date: CalendarDate }) {
  const ref = useRef<HTMLDivElement>(null);
  const { cellProps, buttonProps, isSelected, isOutsideVisibleRange, isDisabled, isUnavailable, isFocused, formattedDate } = useCalendarCell(
    { date },
    state,
    ref,
  );
  return (
    <td {...cellProps} className="sp-calendar__cell">
      <div
        {...buttonProps}
        ref={ref}
        className="sp-calendar__day"
        data-selected={isSelected || undefined}
        data-today={isToday(date, getLocalTimeZone()) || undefined}
        data-outside={isOutsideVisibleRange || undefined}
        data-disabled={isDisabled || undefined}
        data-unavailable={isUnavailable || undefined}
        data-focused={isFocused || undefined}
      >
        {formattedDate}
      </div>
    </td>
  );
}

export default Calendar;

import React, { useRef } from 'react';
import { I18nProvider, useButton, useDateField, useDatePicker, useDateSegment, useDialog, useLocale } from 'react-aria';
import { useDateFieldState, useDatePickerState, DateFieldState, DateSegment } from 'react-stately';
import { DateValue, createCalendar } from '@internationalized/date';
import type { AriaDateFieldProps, AriaDialogProps } from 'react-aria';
import { CalendarCore, CalendarProps } from './Calendar';
import { Popover } from '../base/Popover';
import { useDefaults, slot, ClassNames } from '../internal/defaults';
import { CalendarSystem, FirstDayOfWeek, fromDateValue, toDateValue, toFirstDay, toISO, withCalendar } from './dateAdapters';

export interface DatePickerProps
  extends Pick<CalendarProps, 'min' | 'max' | 'isDateDisabled' | 'firstDayOfWeek' | 'weekStartsOn' | 'locale' | 'calendar' | 'todayLabel'> {
  /** Visible label above the field. */
  label?: React.ReactNode;
  /** Accessible name when there is no visible label. */
  'aria-label'?: string;
  /** Controlled value; `null` for no date. */
  value?: Date | null;
  /** Initial value when uncontrolled. */
  defaultValue?: Date | null;
  /** Called with the picked or typed date, or `null` when cleared. */
  onChange?: (date: Date | null) => void;
  /** Help text under the field (or the error message when `error` is set). */
  helperText?: React.ReactNode;
  /** Marks the field invalid. */
  error?: boolean;
  disabled?: boolean;
  required?: boolean;
  /** Show a clear button when a date is set. Default `true`. */
  clearable?: boolean;
  /** Name for a hidden input carrying the ISO date (YYYY-MM-DD), for plain forms. */
  name?: string;
  /** Default `medium`. */
  size?: 'small' | 'medium' | 'large';
  /** @deprecated The field now shows editable segments in the locale's order. */
  placeholder?: string;
  /** @deprecated The field now shows editable segments in the locale's order. */
  format?: Intl.DateTimeFormatOptions;
  className?: string;
  /** Extra classes for each part: root, label, control, field, trigger, popover, helper. */
  classNames?: ClassNames<'root' | 'label' | 'control' | 'field' | 'trigger' | 'popover' | 'helper'>;
}

/**
 * DatePicker: type a date or pick it from a calendar. The field lights up
 * while the calendar is open, and the picked day is a lit node with a spark.
 * Behaviour comes from React Aria: segment-by-segment typing in the
 * locale's order (DD/MM/YYYY in India, MM/DD/YYYY in the US), arrow keys to
 * adjust a segment, right-to-left layouts, other calendar systems, and a
 * dialog popover that restores focus.
 *
 * Style hooks: `.sp-date-picker[data-open][data-invalid][data-disabled]`,
 * `__label`, `__control`, `.sp-date-field`, `__segment[data-placeholder]`,
 * `__trigger`, `__clear`, `__helper`, `__popover`.
 */
export function DatePicker(inProps: DatePickerProps) {
  const props = useDefaults('DatePicker', inProps);
  const { locale: inherited } = useLocale();
  return (
    <I18nProvider locale={withCalendar(props.locale ?? inherited, props.calendar)}>
      <DatePickerInner {...props} />
    </I18nProvider>
  );
}

function DatePickerInner({
  label,
  'aria-label': ariaLabel,
  value,
  defaultValue,
  onChange,
  min,
  max,
  isDateDisabled,
  firstDayOfWeek,
  weekStartsOn,
  todayLabel,
  helperText,
  error,
  disabled,
  required,
  clearable = true,
  name,
  size = 'medium',
  className,
  classNames,
}: DatePickerProps) {
  const { direction } = useLocale();
  const firstDay = firstDayOfWeek ?? toFirstDay(weekStartsOn);
  const ariaProps = {
    label,
    'aria-label': ariaLabel,
    value: value === undefined ? undefined : toDateValue(value),
    defaultValue: toDateValue(defaultValue),
    onChange: (v: DateValue | null) => onChange?.(fromDateValue(v)),
    minValue: toDateValue(min) ?? undefined,
    maxValue: toDateValue(max) ?? undefined,
    isDateUnavailable: isDateDisabled ? (d: DateValue) => isDateDisabled(fromDateValue(d)!) : undefined,
    isDisabled: disabled,
    isRequired: required,
    isInvalid: error,
    validationBehavior: 'aria' as const,
    description: !error && helperText ? helperText : undefined,
    errorMessage: error && helperText ? helperText : undefined,
    granularity: 'day' as const,
    firstDayOfWeek: firstDay,
    shouldCloseOnSelect: true,
  };
  const state = useDatePickerState(ariaProps);
  const groupRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const { groupProps, labelProps, fieldProps, buttonProps, dialogProps, calendarProps, descriptionProps, errorMessageProps } = useDatePicker(
    ariaProps,
    state,
    groupRef,
  );
  const { buttonProps: triggerButtonProps } = useButton(buttonProps, triggerRef);

  return (
    <div
      className={slot('sp-date-picker', classNames, 'root', className)}
      dir={direction}
      data-tone={error ? 'error' : 'brand'}
      data-size={size}
      data-open={state.isOpen || undefined}
      data-invalid={error || undefined}
      data-disabled={disabled || undefined}
      data-empty={!state.value || undefined}
    >
      {label && (
        <span {...labelProps} className={slot('sp-date-picker__label', classNames, 'label')}>
          {label}
          {required && (
            <span className="sp-field__required" aria-hidden="true">
              {' '}*
            </span>
          )}
        </span>
      )}
      <div {...groupProps} ref={groupRef} className={slot('sp-date-picker__control', classNames, 'control')}>
        <DateField {...fieldProps} className={slot('sp-date-field', classNames, 'field')} />
        {clearable && state.value && !disabled && (
          <button type="button" aria-label="Clear date" className="sp-date-picker__clear" onClick={() => state.setValue(null)}>
            <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true">
              <path d="M3 3l10 10M13 3L3 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        )}
        <button {...triggerButtonProps} ref={triggerRef} className={slot('sp-date-picker__trigger', classNames, 'trigger')}>
          <svg className="sp-date-picker__icon" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
            <rect x="3" y="5" width="18" height="16" rx="2" fill="none" stroke="currentColor" strokeWidth="2" />
            <path d="M3 10h18M8 3v4M16 3v4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        </button>
      </div>
      {helperText && (
        <p {...(error ? errorMessageProps : descriptionProps)} className={slot('sp-date-picker__helper', classNames, 'helper')}>
          {helperText}
        </p>
      )}
      {name && <input type="hidden" name={name} value={toISO(state.value)} />}
      {state.isOpen && (
        <Popover state={state} triggerRef={groupRef} offset={8} className={slot('sp-date-picker__popover', classNames, 'popover')}>
          <Dialog {...dialogProps}>
            <CalendarCore {...calendarProps} firstDayOfWeek={firstDay} todayLabel={todayLabel} />
          </Dialog>
        </Popover>
      )}
    </div>
  );
}

function DateField({ className, ...props }: AriaDateFieldProps<DateValue> & { className: string }) {
  const { locale } = useLocale();
  const state = useDateFieldState({ ...props, locale, createCalendar });
  const ref = useRef<HTMLDivElement>(null);
  const { fieldProps } = useDateField(props, state, ref);
  return (
    <div {...fieldProps} ref={ref} className={className}>
      {state.segments.map((segment, i) => (
        <Segment key={i} segment={segment} state={state} />
      ))}
    </div>
  );
}

function Segment({ segment, state }: { segment: DateSegment; state: DateFieldState }) {
  const ref = useRef<HTMLSpanElement>(null);
  const { segmentProps } = useDateSegment(segment, state, ref);
  return (
    <span
      {...segmentProps}
      ref={ref}
      className="sp-date-field__segment"
      data-type={segment.type}
      data-placeholder={segment.isPlaceholder || undefined}
      data-literal={segment.type === 'literal' || undefined}
    >
      {segment.text}
    </span>
  );
}

function Dialog({ children, ...props }: AriaDialogProps & { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const { dialogProps } = useDialog(props, ref);
  return (
    <div {...dialogProps} ref={ref} className="sp-date-picker__dialog">
      {children}
    </div>
  );
}

export type { FirstDayOfWeek, CalendarSystem };
export default DatePicker;

import { CalendarDate, DateValue, GregorianCalendar, fromDate, getLocalTimeZone, toCalendar, toCalendarDate } from '@internationalized/date';

/**
 * Spark UI's public date props use plain JS `Date`s; React Aria works with
 * `@internationalized/date` values. These helpers convert at the boundary.
 */
export const toDateValue = (d: Date | null | undefined): CalendarDate | null | undefined =>
  d === undefined ? undefined : d === null ? null : toCalendarDate(fromDate(d, getLocalTimeZone()));

export const fromDateValue = (v: DateValue | null | undefined): Date | null => (v ? v.toDate(getLocalTimeZone()) : null);

/** ISO `YYYY-MM-DD` in the Gregorian calendar, whatever calendar is displayed. */
export const toISO = (v: DateValue | null | undefined) => (v ? toCalendar(toCalendarDate(v), new GregorianCalendar()).toString() : '');

/** Calendar systems Intl understands, e.g. `indian`, `islamic-umalqura`, `buddhist`, `persian`, `japanese`. */
export type CalendarSystem =
  | 'gregory'
  | 'indian'
  | 'islamic-umalqura'
  | 'islamic-civil'
  | 'islamic-tbla'
  | 'buddhist'
  | 'persian'
  | 'japanese'
  | 'hebrew'
  | 'ethiopic'
  | 'coptic'
  | 'roc';

/** Add a calendar system to a locale: ('hi-IN', 'indian') → 'hi-IN-u-ca-indian'. */
export const withCalendar = (locale: string, calendar?: CalendarSystem) =>
  calendar ? `${locale.replace(/-u-ca-[a-z-]+$/, '')}-u-ca-${calendar}` : locale;

const days = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'] as const;
export type FirstDayOfWeek = (typeof days)[number];
/** Old numeric `weekStartsOn` (0 = Sunday) to React Aria's `firstDayOfWeek`. */
export const toFirstDay = (n?: number): FirstDayOfWeek | undefined => (n === undefined ? undefined : days[((n % 7) + 7) % 7]);

export { DatePicker } from './DatePicker';
export type { DatePickerProps } from './DatePicker';
export { Calendar } from './Calendar';
export type { CalendarProps } from './Calendar';
export type { CalendarSystem, FirstDayOfWeek } from './dateAdapters';
